V=/var/www/vhosts/enricgomez.com
T=$V/httpdocs/wp-content/themes/eg-studio/assets
echo  | base64 -d > /tmp/eg-robots.txt
echo  | base64 -d > /tmp/eg-extra.md
echo  | base64 -d > /tmp/eg-fix.php
chmod 644 /tmp/eg-robots.txt /tmp/eg-extra.md /tmp/eg-fix.php
[ -f $T/eg.src.js ] || cp -p $T/eg.js $T/eg.src.js
echo  | base64 -d > /tmp/eg-min.js && [ -s /tmp/eg-min.js ] && cat /tmp/eg-min.js > $T/eg.js && chown enricgomez:psacln $T/eg.js $T/eg.src.js && wc -c $T/eg.js $T/eg.src.js
sudo -u enricgomez HOME=/tmp /opt/plesk/php/8.5/bin/php /usr/local/bin/wp --path=$V/httpdocs eval-file /tmp/eg-fix.php 2>&1 | grep -v "PHP:\|trace\|#0\|^)\]\|^'"
grep -rn "apply_filters" $V/httpdocs/wp-content/plugins/seo-by-rank-math/includes/modules/llms 2>/dev/null | head; grep -rln "llms_post_types" $V/httpdocs/wp-content/plugins/seo-by-rank-math/includes | head -3
rm -f /tmp/eg-fix.php /tmp/eg-min.js
